        update system_burying_point_record
        set numbers=numbers+1 ,
            length_of_stay=length_of_stay+#{vo.lengthOfStay},
            insert_time=#{vo.insertTime}
        where  user_id=#{vo.userId} and dates = #{vo.dates}
                and environment=#{vo.environment}  and dim= #{vo.dim}
                and home_page=#{vo.homePage} and field_page=#{vo.fieldPage}
                and indicator_page=#{vo.indicatorPage} ;

mapper.select:
select * from 
system_burying_point_record
WHERE user_id = #{vo.userId} and dates = #{vo.dates}
        and environment = #{vo.environment}
        and dim = #{vo.dim} and home_page = #{vo.homePage}
        and field_page = #{vo.fieldPage} and indicator_page = #{vo.indicatorPage}

select * from
    system_burying_point_record
WHERE environment = #{environment}
  and dates  >=  #{startTime} and dates  <=  #{endTime}
ORDER BY dates
